metadata.preview:
{
  "schema_version": 1,
  "name": "probed_referent_likelihood_rating",
  "summary": "7-point Likert likelihood ratings of a single probed candidate referent across 2-5 objects and 2-4 features with informative and prior queries and synonyms, testing whether reference theories generalize from multi-object allocation and forced choice to targeted single-referent evaluation.",
  "charter": {
    "question": "When listeners evaluate the likelihood of a single highlighted candidate referent on a 7-point scale across informative and prior trials spanning 2-5 objects and 2-4 features, do their graded judgments follow singleton-only bounded-depth RSA, a shared multi-cue structural prior (feature complexity and Hamming distinctiveness), a feature-parsimony penalty, or depth-2 recursive inference?"
  },
  "instructions": {
    "welcome": "Welcome! In this short study, you will play a communication game where a speaker describes one of the objects on the screen.",
    "task": "On each turn, you and the speaker see the same row of objects, and one object is highlighted with an orange frame. The speaker has one target object in mind and says a single word that names a part on their target object. Your job is to rate how likely it is that the highlighted object is the speaker's target on a scale from 1 (Definitely not) to 7 (Definitely). If the highlighted object does not have the named part, it cannot be the target (rate it 1). If the highlighted object is the only object that has the named part, it is definitely the target (rate it 7). If more than one object has the named part, use the 1 to 7 scale to show how likely the highlighted object is to be the target. On some turns, the speaker's word was cut off; on those turns, rate how likely it is that the speaker is talking about the highlighted object.",
    "comprehension_checks": [
      {
        "question": "What are you rating on each turn?",
        "options": [
          "How likely it is that the highlighted object (in the orange frame) is the speaker's target, from 1 to 7",
          "How many total parts all the objects have combined",
          "Which word the speaker should have said instead"
        ],
        "correct": 0
      },

