{
  "schema_version": 1,
  "name": "speaker_acceptability_judgment",
  "summary": "Binary speaker message acceptability judgments (Yes/No) on whether a speaker would use a given word to describe a highlighted target object across 2-5 objects and 2-4 features across three visual domains (robots, snowmen, houses).",
  "charter": {
    "question": "When participants evaluate whether a speaker would choose a specific referring expression to describe a highlighted target referent (binary acceptability judgment), do their speaker expectations reflect depth-1 pragmatic listeners with continuous contextual distinctiveness, singleton-only bounded-depth listeners, feature parsimony, depth-2 recursive listeners, or referential feature uncertainty?"
  },
  "instructions": {
    "welcome": "Welcome! In this short study, you will play a communication game where a speaker describes one of the objects on the screen.",
    "task": "On each turn, you and the speaker see the same row of objects. The speaker wants to refer to the highlighted object (in the orange frame) by saying a single word that names one of its parts. You will see a candidate word and decide whether the speaker would say that word to refer to the highlighted object (Yes or No). If the highlighted object does not have the named part, answer No. If the highlighted object is the only object that has the named part, answer Yes. If more than one object has the named part, decide whether the speaker would still use that word for the highlighted object.",
    "comprehension_checks": [
      {
        "question": "What are you deciding on each turn?",
        "options": [
          "Whether the speaker would say the shown word to refer to the highlighted object (in the orange frame)",
          "How many total objects are on the screen",
          "Whether all objects are identical"
        ],
        "correct": 0
      },

